def clean(df):
    df = df.copy()
    # Fix species case variants
    species_map = {'gentoo': 'Gentoo', 'adelie': 'Adelie', 'chinstrap': 'Chinstrap'}
    df['species'] = df['species'].replace(species_map)
    # Fix island typos/variants
    island_map = {'Bisco': 'Biscoe', 'Dram': 'Dream'}
    df['island'] = df['island'].replace(island_map)
    # Fix negative flipper lengths (sign error)
    df['flipper_length_mm'] = df['flipper_length_mm'].astype(float).abs()
    # Convert text numbers to numeric
    for col in ['body_mass_g', 'year']:
        df[col] = pd.to_numeric(df[col], errors='coerce')
    # Remove exact duplicate rows
    df = df.drop_duplicates()
    return df

def answer(df):
    df = clean(df)
    counts = df.groupby('island').size()
    return {k: int(v) for k, v in counts.items()}
